// 1) make sure every file that uses $this->l10n->t() imports IL10N
const libDir = path.join(ROOT, 'lib')
const walk = (dir) =>
	fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
		const full = path.join(dir, e.name)
		return e.isDirectory() ? walk(full) : full.endsWith('.php') ? [full] : []
	})

let importsAdded = 0
for (const file of walk(libDir)) {
	let text = fs.readFileSync(file, 'utf8')
	if (!text.includes('$this->l10n->t(')) continue
	if (text.includes('use OCP\\IL10N;')) continue
	const anyUse = [...text.matchAll(/^use [^\n]*\n/gm)].pop()
	if (!anyUse) {
		console.log(`NO USE STMT: ${path.relative(ROOT, file)}`)
		continue
	}
	text = text.replace(anyUse[0], anyUse[0] + 'use OCP\\IL10N;\n')
	fs.writeFileSync(file, text)
	importsAdded++
	console.log(`added IL10N import: ${path.relative(ROOT, file)}`)
}

// 2) merge the hand-written translations into the catalogue
const l10nPath = path.join(ROOT, 'l10n', 'zh_CN.json')
const data = JSON.parse(fs.readFileSync(l10nPath, 'utf8'))
let added = 0
for (const [en, zh] of Object.entries(ZH)) {
	if (!data.translations[en]) added++
	data.translations[en] = zh
}
const sorted = Object.fromEntries(Object.entries(data.translations).sort(([a], [b]) => a.localeCompare(b)))
fs.writeFileSync(l10nPath, JSON.stringify({ translations: sorted, pluralForm: data.pluralForm }, null, 2) + '\n')
fs.writeFileSync(
	path.join(ROOT, 'l10n', 'zh_CN.js'),
	`OC.L10N.register(\n\t"todofolder",\n\t${JSON.stringify(sorted, null, 2).replace(/\n/g, '\n\t')},\n\t"nplurals=1; plural=0;"\n);\n`,
)

// 3) every t('...') key in lib/ should exist in the catalogue
const missing = new Set()
for (const file of walk(libDir)) {
	const text = fs.readFileSync(file, 'utf8')
	for (const m of text.matchAll(/\$this->l10n->t\('((?:[^'\\]|\\.)*)'/g)) {
		const key = m[1].replace(/\\'/g, "'")
		if (!sorted[key]) missing.add(`${path.relative(ROOT, file)} :: ${key}`)
	}
}
console.log(`imports added: ${importsAdded}, catalogue: ${Object.keys(sorted).length} entries (+${added})`)
if (missing.size) {
	console.log('KEYS MISSING FROM CATALOGUE:')
	;[...missing].forEach((m) => console.log('  ' + m))
}
